133	// validateConfig 校验配置必须是合法的 JSON 对象，并返回独立副本。
134	func validateConfig(raw json.RawMessage) (json.RawMessage, error) {
135		if _, ok := decodeObject(raw); !ok {
136			return nil, ErrInvalidConfig
137		}
