190			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
191			At: upBase.Add(time.Minute), Success: true,
192		}); err != nil {
193			t.Fatalf("download: %v", err)
194		}
195		dir := s.dir
196		if err := s.Close(); err != nil {
197			t.Fatal(err)
198		}
199		return s, dir, spec
