package shadow

import (
	"encoding/json"
	"errors"
	"testing"
	"time"
)

// 重复上报成功返回但不重新写入影子：设备已被 SetOffline 标为离线后，
// 同序号同内容（版本、发生时间、配置一致）的重发不得把设备重新置为在线；
// 更大序号的有效上报才重新上线。
func TestReportDuplicateKeepsOfflineAndDoesNotRewrite(t *testing.T) {
	s, _ := openTemp(t)
	mustRegister(t, s, "dev-1", "1.0")
	at := base
	if err := s.Report("dev-1", 1, at, "1.1", json.RawMessage(`{"cpu":80}`)); err != nil {
		t.Fatal(err)
	}
	if err := s.SetOffline("dev-1"); err != nil {
		t.Fatal(err)
	}
	// 完全重复：成功返回，设备保持离线，影子不重写。
	if err := s.Report("dev-1", 1, at, "1.1", json.RawMessage(` { "cpu": 80 } `)); err != nil {
		t.Fatalf("duplicate report should succeed: %v", err)
	}
	v, _ := s.Get("dev-1")
	if v.Online {
		t.Fatal("duplicate report must not bring an offline device online")
	}
	if v.Version != "1.1" || v.LastSeq != 1 || string(v.Reported) != `{"cpu":80}` {
		t.Fatalf("duplicate report rewrote shadow: %+v", v)
	}
	// 同序号内容不同仍是冲突，不改变离线状态。
	if err := s.Report("dev-1", 1, at, "1.1", json.RawMessage(`{"cpu":81}`)); err == nil {
		t.Fatal("same seq with different content must conflict")
	}
	if v, _ = s.Get("dev-1"); v.Online {
		t.Fatal("conflicting report changed online state")
	}
	// 更大序号的有效上报重新上线并写入。
	if err := s.Report("dev-1", 2, at.Add(time.Minute), "1.2", json.RawMessage(`{"cpu":90}`)); err != nil {
		t.Fatal(err)
	}
	if v, _ = s.Get("dev-1"); !v.Online || v.Version != "1.2" || v.LastSeq != 2 {
		t.Fatalf("larger seq should update and bring online: %+v", v)
	}
}

// 安装成功附带的上报若已被普通上报以相同序号接受（版本、发生时间、配置均
// 一致），提交安装结果仍能完成设备与活动，但不重新写入影子：不刷新在线
// 状态（离线设备保持离线），也不刷新差异首次出现时间。
func TestInstallAttachedReportAcceptedByPlainReportCompletesWithoutRewrite(t *testing.T) {
	s := setupUpgrade(t, "d1")
	spec := upSpec()
	spec.Devices = []string{"d1"}
	spec.BatchSize = 1
	createCampaign(t, s, spec)
	bringOnline(t, s, "d1")

	// 先制造一条持续存在的差异，记录其首次出现时间。
	desiredAt := upBase.Add(-2 * time.Minute)
	if _, err := s.UpdateDesired("d1", "bob", desiredAt, 0, json.RawMessage(`{"x":1}`)); err != nil {
		t.Fatal(err)
	}
	dl, _ := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
		At: upBase.Add(3 * time.Minute), Success: true,
	}); err != nil {
		t.Fatal(err)
	}
	in, _ := s.Claim(spec.ID, "d1", upBase.Add(4*time.Minute))

	// 普通上报先以安装附带上报将使用的同一序号/时间/版本/配置被接受。
	reportAt := upBase.Add(5 * time.Minute)
	cfg := json.RawMessage(`{"x":2}`)
	if err := s.Report("d1", 2, reportAt, "v2", cfg); err != nil {
		t.Fatal(err)
	}
	diffsBefore, _ := s.Diff("d1")
	sinceBefore := diffsBefore[0].Since
	if !sinceBefore.Equal(desiredAt) {
		t.Fatalf("/x should already exist since desired update: %v", sinceBefore)
	}
	// 设备随后被标为离线：附带的重复上报不得把它重新置为在线。
	if err := s.SetOffline("d1"); err != nil {
		t.Fatal(err)
	}
	cv0, _ := s.GetCampaign(spec.ID)
	nResults := len(cv0.Results)

	// 提交安装成功：附带上报与影子中已接受的内容完全一致，按重复处理，
	// 但安装操作本身正常完成、历史照常增加一条。
	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
		At: reportAt, Success: true,
		Seq: 2, Version: "v2", Config: json.RawMessage(` { "x": 2.0 } `),
	}); err != nil {
		t.Fatalf("install with already-accepted report should succeed: %v", err)
	}
	cv, _ := s.GetCampaign(spec.ID)
	d := findDevice(cv, "d1")
	if d.Status != DeviceSucceeded || !cv.Ended || cv.Status != CampaignSucceeded {
		t.Fatalf("install should complete: %+v device=%+v", cv, d)
	}
	if len(cv.Results) != nResults+1 {
		t.Fatalf("install result must enter history: %+v", cv.Results)
	}
	// 影子未被重新写入：设备保持离线，序号/版本/配置不变。
	v, _ := s.Get("d1")
	if v.Online {
		t.Fatal("duplicate attached report must not refresh online state")
	}
	if v.Version != "v2" || v.LastSeq != 2 || string(v.Reported) != `{"x":2}` {
		t.Fatalf("shadow rewritten by duplicate attached report: %+v", v)
	}
	// 差异仍在，且首次出现时间未被安装时间刷新。
	diffs, _ := s.Diff("d1")
	if len(diffs) != 1 || diffs[0].Path != "/x" || !diffs[0].Since.Equal(sinceBefore) {
		t.Fatalf("diff since refreshed: %+v", diffs)
	}
	// 已接受安装结果的重复提交仍成功且不增加历史。
	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
		At: reportAt.Add(time.Hour), Success: true,
		Seq: 2, Version: "v2", Config: json.RawMessage(`{"x":2}`),
	}); err != nil {
		t.Fatalf("replay accepted install: %v", err)
	}
	if cv2, _ := s.GetCampaign(spec.ID); len(cv2.Results) != len(cv.Results) {
		t.Fatal("replay added history")
	}
}

// 回滚成功附带的上报已被普通上报以相同序号接受时，回滚仍能完成（活动因
// 回滚按规则失败结束），但影子不重新写入：离线设备保持离线，版本/序号/
// 上报配置不变；期望配置、修订号与审计不受影响。
func TestRollbackAttachedReportAcceptedByPlainReportCompletesWithoutRewrite(t *testing.T) {
	s := setupUpgrade(t, "d1")
	spec := rbSpec()
	createCampaign(t, s, spec)
	bringOnline(t, s, "d1")
	if _, err := s.UpdateDesired("d1", "bob", upBase.Add(-2*time.Minute), 0, json.RawMessage(`{"x":1}`)); err != nil {
		t.Fatal(err)
	}
	awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
	rb, err := s.Claim(spec.ID, "d1", upBase.Add(6*time.Minute))
	if err != nil || rb == nil || rb.Kind != StageRollback {
		t.Fatalf("claim rollback: %v %+v", err, rb)
	}

	// 普通上报先接受回滚附带上报将使用的同一序号/时间/版本/配置。
	reportAt := upBase.Add(7 * time.Minute)
	if err := s.Report("d1", 2, reportAt, "v1", json.RawMessage(`{"x":2}`)); err != nil {
		t.Fatal(err)
	}
	if err := s.SetOffline("d1"); err != nil {
		t.Fatal(err)
	}
	cv0, _ := s.GetCampaign(spec.ID)
	nResults := len(cv0.Results)

	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
		At: reportAt, Success: true,
		Seq: 2, Version: "v1", Config: json.RawMessage(`{"x": 2.0}`),
	}); err != nil {
		t.Fatalf("rollback with already-accepted report should succeed: %v", err)
	}
	cv, _ := s.GetCampaign(spec.ID)
	d := findDevice(cv, "d1")
	if d.Status != DeviceRollbackSucceeded {
		t.Fatalf("rollback should complete: %+v", d)
	}
	if !cv.Ended || cv.Status != CampaignFailed {
		t.Fatalf("campaign fails even after successful rollback: %+v", cv)
	}
	if len(cv.Results) != nResults+1 {
		t.Fatalf("rollback result must enter history: %+v", cv.Results)
	}
	v, _ := s.Get("d1")
	if v.Online {
		t.Fatal("duplicate attached rollback report must not refresh online state")
	}
	if v.Version != "v1" || v.LastSeq != 2 || string(v.Reported) != `{"x":2}` {
		t.Fatalf("shadow rewritten by duplicate attached report: %+v", v)
	}
	if v.Revision != 1 || string(v.Desired) != `{"x":1}` {
		t.Fatalf("desired/revision changed: %+v", v)
	}
	if auds, _ := s.Audit("d1"); len(auds) != 1 {
		t.Fatalf("audit changed: %+v", auds)
	}
	// 回滚结果接受后再改用不同配置重提：按已接受结果冲突拒绝（既有幂等
	// 语义），不增加历史、不改状态。
	if err := s.SubmitResult(OperationResult{
		CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
		At: upBase.Add(8 * time.Minute), Success: true,
		Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":9}`),
	}); !errors.Is(err, ErrResultConflict) {
		t.Fatalf("changed accepted result should conflict: %v", err)
	}
}

package shadow

import "errors"

// 设备影子操作的错误。调用方可用 errors.Is 判断。
var (
	// ErrInvalidDeviceID 表示设备标识为空。
	ErrInvalidDeviceID = errors.New("shadow: device id must not be empty")
	// ErrInvalidVersion 表示版本为空。
	ErrInvalidVersion = errors.New("shadow: version must not be empty")
	// ErrInvalidOperator 表示操作者为空。
	ErrInvalidOperator = errors.New("shadow: operator must not be empty")
	// ErrInvalidTime 表示操作时间缺失（零值）。
	ErrInvalidTime = errors.New("shadow: operation time must not be zero")
	// ErrInvalidConfig 表示配置不是合法的 JSON 对象。
	ErrInvalidConfig = errors.New("shadow: config must be a valid JSON object")
	// ErrDeviceExists 表示重复登记同一设备。
	ErrDeviceExists = errors.New("shadow: device already registered")
	// ErrDeviceNotFound 表示访问未登记的设备。
	ErrDeviceNotFound = errors.New("shadow: device not found")
	// ErrRevisionConflict 表示提交的期望修订号与当前值不一致。
	ErrRevisionConflict = errors.New("shadow: desired revision conflict")
	// ErrInvalidSequence 表示上报序号不是正整数。
	ErrInvalidSequence = errors.New("shadow: report sequence must be a positive integer")
	// ErrStaleSequence 表示上报序号小于已接受的序号。
	ErrStaleSequence = errors.New("shadow: report sequence is stale")
	// ErrReportConflict 表示相同序号的上报内容不一致。
	ErrReportConflict = errors.New("shadow: report conflicts with accepted sequence")
	// ErrCorruptStorage 表示已有存储内容损坏，拒绝打开。
	ErrCorruptStorage = errors.New("shadow: storage is corrupt")
	// ErrClosed 表示存储已关闭。
	ErrClosed = errors.New("shadow: store is closed")

	// 分批升级相关错误。
	// ErrInvalidVersionList 表示允许升级的版本列表为空、含空串或含目标版本。
	ErrInvalidVersionList = errors.New("shadow: allowed-from version list invalid")
	// ErrVersionExists 表示重复登记同一目标版本，原记录保留。
	ErrVersionExists = errors.New("shadow: upgrade target version already registered")
	// ErrVersionNotFound 表示引用的升级目标版本未登记。
	ErrVersionNotFound = errors.New("shadow: upgrade target version not found")
	// ErrInvalidCampaignID 表示活动标识为空。
	ErrInvalidCampaignID = errors.New("shadow: campaign id must not be empty")
	// ErrInvalidDeviceList 表示活动设备列表为空。
	ErrInvalidDeviceList = errors.New("shadow: campaign device list must not be empty")
	// ErrDuplicateDevice 表示活动设备列表中设备重复。
	ErrDuplicateDevice = errors.New("shadow: campaign device list contains duplicates")
	// ErrInvalidBatchSize 表示批大小不是正整数。
	ErrInvalidBatchSize = errors.New("shadow: batch size must be a positive integer")
	// ErrInvalidWindow 表示维护窗口开始时刻不早于结束时刻。
	ErrInvalidWindow = errors.New("shadow: maintenance window start must be before end")
	// ErrInvalidDeadline 表示截止时间不晚于创建时间。
	ErrInvalidDeadline = errors.New("shadow: deadline must be after creation time")
	// ErrCampaignExists 表示活动标识重复。
	ErrCampaignExists = errors.New("shadow: campaign already exists")
	// ErrCampaignNotFound 表示访问不存在的活动。
	ErrCampaignNotFound = errors.New("shadow: campaign not found")
	// ErrDeviceNotInCampaign 表示设备不属于该活动。
	ErrDeviceNotInCampaign = errors.New("shadow: device is not in campaign")
	// ErrDeviceBusy 表示设备已参加尚未结束的活动。
	ErrDeviceBusy = errors.New("shadow: device already in an active campaign")
	// ErrIncompatibleVersion 表示设备当前版本不在允许升级的版本列表中。
	ErrIncompatibleVersion = errors.New("shadow: device version is not compatible")
	// ErrTimeRegression 表示同一活动传入的当前时间早于已接受的时间。
	ErrTimeRegression = errors.New("shadow: campaign time must not go backwards")
	// ErrCampaignEnded 表示活动已结束，不再接受新操作。
	ErrCampaignEnded = errors.New("shadow: campaign has ended")
	// ErrDeviceFinished 表示设备在活动中已处于终态。
	ErrDeviceFinished = errors.New("shadow: device already finished in campaign")
	// ErrBatchWaiting 表示设备所在批次尚未放行（前一批未全部成功）。
	ErrBatchWaiting = errors.New("shadow: device batch is waiting for previous batches")
	// ErrOperationNotClaimed 表示为尚未领取的操作提交结果（含跳过阶段）。
	ErrOperationNotClaimed = errors.New("shadow: operation has not been claimed")
	// ErrOperationNotFound 表示操作标识未知或属于其他设备/活动。
	ErrOperationNotFound = errors.New("shadow: operation not found")
	// ErrResultConflict 表示同一操作改用与已接受结果不同的结果。
	ErrResultConflict = errors.New("shadow: result conflicts with accepted result")
	// ErrInvalidReason 表示失败结果未附带原因。
	ErrInvalidReason = errors.New("shadow: failure result requires a reason")
	// ErrInvalidReport 表示安装成功未附带符合上报规则、版本等于目标版本的设备上报。
	ErrInvalidReport = errors.New("shadow: install success requires a valid device report at target version")

	// 批量修改期望配置相关错误。
	// ErrInvalidRequestID 表示批量请求标识为空。
	ErrInvalidRequestID = errors.New("shadow: request id must not be empty")
	// ErrRequestConflict 表示同一请求标识被内容不同的批量请求重复使用，原结果保持有效。
	ErrRequestConflict = errors.New("shadow: request id reused with different content")
	// ErrRequestNotFound 表示按标识查询的批量请求不存在（含从未成功提交的请求）。
	ErrRequestNotFound = errors.New("shadow: batch request not found")
)

