361		// b1 完整成功
362		finishDevice(t, s, spec, "b1", upBase.Add(2*time.Minute))
363		// b2 下载失败
364		dl, err := s.Claim(spec.ID, "b2", upBase.Add(6*time.Minute))
365		if err != nil {
366			t.Fatal(err)
367		}
368		failAt := upBase.Add(7 * time.Minute)
369		if err := s.SubmitResult(OperationResult{
370			CampaignID: spec.ID, DeviceID: "b2", OperationID: dl.ID,
371			At: failAt, Success: false, Reason: "download broken",
372		}); err != nil {
373			t.Fatal(err)
374		}
375	
376		v, err := s.GetCampaign(spec.ID)
377		if err != nil {
378			t.Fatal(err)
379		}
380		st := map[string]DeviceStatusView{}
381		for _, d := range v.Devices {
382			st[d.DeviceID] = d
383		}
384		if st["b2"].Status != DeviceFailed || st["b2"].Phase != StageDownload ||
385			st["b2"].Reason != "download broken" || !st["b2"].At.Equal(failAt) {
386			t.Fatalf("b2 failure record: %+v", st["b2"])
387		}
388		// 后续批次全部记为未执行
389		for _, id := range []string{"b3", "b4"} {
390			if st[id].Status != DeviceSkipped {
391				t.Fatalf("%s should be skipped: %+v", id, st[id])
392			}
393		}
394		// 失败后活动立即结束（设备均有终态）
395		if !v.Ended || v.Status != CampaignFailed {
396			t.Fatalf("campaign should end failed: %+v", v)
397		}
398		// 失败/超时原因和结果历史可查
399		if len(v.Results) != 3 { // b1 下载、b1 安装、b2 下载失败
400			t.Fatalf("result history: %+v", v.Results)
401		}
